// lookup demo — Buttermilk (jahdb demo program)
var DATA={"Buttermilk":"No buttermilk: milk plus acid curdles into a fine substitute for pancakes and biscuits."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("1 cup milk + 1 tbsp lemon juice or vinegar, rest 5 min"));

